#!/usr/bin/env python3
"""docs/TEST_RESULTS.md (generated by tools/run_all_tests.sh) + source files -> results/derived/readme_data.json."""
import json, os, re, wave
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
P = lambda *a: os.path.join(ROOT, *a)
txt = open(P("docs/TEST_RESULTS.md")).read()
suites = []
for m in re.finditer(r"^\| (?!Suite|---)(.+?) \| (\d+) passed, (\d+) failed \|", txt, re.M):
    suites.append({"suite": m[1], "passed": int(m[2]), "failed": int(m[3])})
out = {"suites": suites, "total_passed": sum(s["passed"] for s in suites), "total_failed": sum(s["failed"] for s in suites), "suite_count": len(suites)}
out["unit_passed"] = [s for s in suites if s["suite"].startswith("unit")][0]["passed"]
out["integration_passed"] = out["total_passed"] - out["unit_passed"]
out["overall_pass"] = "Overall: PASS" in txt
g = re.search(r"Generated by .* on (\S+ \S+) with (\S+) on macOS (\S+)", txt)
out["reaper"] = g[2].split("_")[0]
# performance (extra_perf section of the same file)
perf = txt[txt.index("## extra_perf"):]
def stat(label):
    m = re.search(label + r".*?mean\s+([\d.]+) ms.*?p95\s+([\d.]+)", perf)
    return {"mean_ms": float(m[1]), "p95_ms": float(m[2])}
out["perf"] = {"idle": stat(r"idle, 16 tracks/100 clips"), "drag": stat(r"dragging a clip"), "playback": stat(r"playback \(meters")}
out["perf_rows"] = [{"case": k, "mean_ms": v["mean_ms"], "p95_ms": v["p95_ms"]} for k, v in
                    (("idle", out["perf"]["idle"]), ("dragging a clip", out["perf"]["drag"]), ("playback", out["perf"]["playback"]))]
out["perf_chart"] = [{"case": r["case"], "stat": st, "ms": r[k]} for r in out["perf_rows"] for st, k in (("mean", "mean_ms"), ("p95", "p95_ms"))]
m = re.search(r"built (\d+) tracks, (\d+) clips, (\d+) notes", perf)
out["bench"] = {"tracks": int(m[1]), "clips": int(m[2]), "notes": int(m[3])}
m = re.search(r"playback cadence >= 20 fps.*?\s([\d.]+)\s*$", perf, re.M)
out["playback_fps"] = round(float(m[1]), 1)
# code size
lua = [os.path.join(d, f) for d, _, fs in os.walk(P("src")) for f in fs if f.endswith(".lua")]
out["src_lines"] = sum(len(open(f).read().splitlines()) for f in lua)
out["src_files"] = len(lua)
w = wave.open(P("docs/demo/neon_drive_export.wav")); out["song_seconds"] = round(w.getnframes() / w.getframerate())
out["shots"] = len([f for f in os.listdir(P("docs/screenshots")) if f.endswith(".png")])
os.makedirs(P("results/derived"), exist_ok=True)
json.dump(out, open(P("results/derived/readme_data.json"), "w"), indent=1)
print(json.dumps(out)[:500])
